mapper.update:
UPDATE followup_record
SET status = #{status},
    cancel_reason = #{cancelReason},
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE followup_record
SET workspace_task_id = #{workspaceTaskId},
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND is_deleted = 0

mapper.sql:
WHERE f.org_id = #{orgId}
  AND f.is_deleted = 0

    AND f.status = #{status}


    AND f.record_type = #{recordType}


    AND EXISTS (
        SELECT 1 FROM people_profile p
        WHERE p.id = f.people_id
          AND p.is_deleted = 0
          AND p.display_name LIKE CONCAT('%', #{keyword}, '%')
    )

mapper.select:
SELECT 
FROM followup_record
WHERE org_id = #{orgId}
  AND people_id = #{peopleId}
  AND is_deleted = 0

    AND record_type = #{recordType}

ORDER BY COALESCE(completed_at, planned_at, gmt_created) DESC, id DESC
LIMIT #{limit}

SELECT 
FROM followup_record
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND is_deleted = 0
  AND status IN ('OPEN', 'DONE')
ORDER BY COALESCE(completed_at, planned_at, gmt_created) DESC, id DESC
LIMIT #{limit}

SELECT 
FROM followup_record
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND is_deleted = 0
  AND status = 'DONE'
  AND completed_at >= #{from}
  AND completed_at < #{to}
ORDER BY completed_at DESC, id DESC
